        if index >= self.count {
            return Err(FileError::Malformed("chunk index exceeds layout".into()));
        }
        let offset = u64::from(index) * u64::from(self.chunk_size);
        Ok((self.size - offset).min(u64::from(self.chunk_size)) as u32)
    }
