                            Ok::<_, Infallible>(vec![Record {
                                id: *id,
                                body: vec![id[0]],
                            }])
                        },
                    )
                    .await
                    .unwrap();
                }
                // The first connection is lost after one acknowledged batch.
            });
        }
        while let Some(result) = tasks.join_next().await {
            result.unwrap();
        }
    })
