            let start = Instant::now();
            let mut rtt = Vec::new();
            for _ in 0..rounds {
                let sent = Instant::now();
                if split {
                    tcp.write_all(&(size as u32).to_be_bytes()).await.unwrap();
                    tcp.write_all(&body).await.unwrap();
                    tcp.flush().await.unwrap();
                } else {
                    write_frame(&mut tcp, &body).await.unwrap();
                }
                assert_eq!(read_frame(&mut tcp).await.unwrap(), body);
                rtt.push(sent.elapsed().as_micros());
            }
            let elapsed = start.elapsed();
            rtt.sort_unstable();
            println!("split={split} size={size} n={rounds} p50_us={} p95_us={} total_ms={} MiB/s={:.2}",
                rtt[rounds/2], rtt[rounds*95/100], elapsed.as_millis(), (2*rounds*size) as f64 / 1048576.0 / elapsed.as_secs_f64());
        },
        async {
            let (mut tcp, _) = listener.accept().await.unwrap();
            for _ in 0..rounds {
                let body = read_frame(&mut tcp).await.unwrap();
                if split {
                    tcp.write_all(&(size as u32).to_be_bytes()).await.unwrap();
                    tcp.write_all(&body).await.unwrap();
                    tcp.flush().await.unwrap();
                } else {
                    write_frame(&mut tcp, &body).await.unwrap();
                }
            }
        }
    );
}

